import json, random, sys, subprocess
sys.path.insert(0,'/workspace/tmp/t')
import fuzz
def why(doc):
    problems=[]
    seen=set()
    for z in doc['zones']:
        o=z['origin'].lower()
        if o in seen: problems.append('dup origin'); 
        seen.add(o)
        for r in z['records']:
            ow=r['owner'].lower()
            labs=ow[:-1].split('.') if ow!='.' else []
            ol=o[:-1].split('.') if o!='.' else []
            if len(labs)<len(ol) or labs[len(labs)-len(ol):]!=ol: problems.append('owner above origin')
    for z in doc['zones']:
        per={}
        for r in z['records']: per.setdefault(r['owner'].lower(),[]).append(r['type'])
        for ow,ts in per.items():
            if 'CNAME' in ts and len(ts)>1: problems.append('cname coexist')
            if 'CNAME' in ts and ow==z['origin'].lower(): problems.append('cname at origin')
    return problems
bad=0; reasons={}
for i in range(1500):
    rng=random.Random(i); doc=fuzz.gen(rng)
    p=subprocess.run([sys.executable,'-I','/workspace/submission/main.py'],input=json.dumps(doc).encode(),capture_output=True)
    out=p.stdout.decode()
    if out.startswith('{"error"'):
        w=why(doc)
        reasons[tuple(w)] = reasons.get(tuple(w),0)+1
        if not w:
            print('UNEXPLAINED', i, json.dumps(doc)[:800]); bad+=1
            if bad>2: break
print('unexplained:', bad)
print(reasons)
PYEOF
